(()=>{
const $=id=>document.getElementById(id),reader=$('magReader');let flip=null,current=0,requestedPage=0;
const titles=['Couverture','Introduction','Histoire · les origines','Histoire · la modernité','À travers les décennies','Chanel et Dior','Louis Vuitton et Hermès','Coco Chanel','Dior et Saint Laurent','Paris Fashion Week','Les coulisses','La mode aujourd’hui','L’influence mondiale','Conclusion','Le dictionnaire','Notre équipe'];
const enTitles=['Cover','Introduction','History · the origins','History · modernity','Through the decades','Chanel and Dior','Louis Vuitton and Hermès','Coco Chanel','Dior and Saint Laurent','Paris Fashion Week','Behind the scenes','Fashion today','Global influence','Conclusion','The dictionary','Our team'];
const lang=()=>window.siteLanguage==='en'?'en':'fr';
const photo=(i)=>'assets/magazine/photo-'+String(i+1).padStart(2,'0')+'.webp';
function englishContent(i){const p=window.magazineEnglish[i];if(p.cover)return `<div class="english-cover"><img src="assets/magazine/photo-01.webp" alt="Fashion photograph from the magazine cover"><div><span>N° 001 · NOVEMBER 2026</span><h2>The evolution of<br>French fashion</h2><p>Through history · The art of fashion</p><p>The names that defined luxury<br>Chanel. Dior. Hermès. Louis Vuitton.</p><p>Paris sets the stage<br>The story behind Fashion Week.</p></div></div>`;return `<article class="english-page ${p.dictionary?'dictionary-page':''} ${p.credits?'credits-page':''}"><header><span>LE DÉFILÉ · ENGLISH READING EDITION</span><small>${i+1} / 16</small></header><p class="english-kicker">${p.sub}</p><h2>${p.title}</h2>${p.credits?'':`<img class="english-photo" src="${photo(i)}" alt="Fashion imagery from the original magazine" loading="lazy">`}<div class="english-copy">${p.body.map(([h,t])=>`<section>${h?`<h3>${h}</h3>`:''}${t?`<p>${t}</p>`:''}</section>`).join('')}</div><div class="english-footer">THE EVOLUTION OF FRENCH FASHION</div></article>`}
function pageHTML(i){return lang()==='en'?englishContent(i):`<img class="original-page" src="assets/magazine/page-${String(i+1).padStart(2,'0')}.webp" alt="Page ${i+1} — ${titles[i]}" ${i>2?'loading="lazy"':''} draggable="false">`}
function pageNodes(){return Array.from({length:16},(_,i)=>{let d=document.createElement('div');d.className='mag-page';d.dataset.noTranslate='';if(i===0||i===15)d.dataset.density='hard';d.innerHTML=pageHTML(i);return d})}
function controls(){let en=lang()==='en';const spread=flip?.getOrientation()==='landscape'&&current>0&&current<15; $('readerPage').textContent=(en?'Page ':'Page ')+(current+1)+(spread?'–'+(current+2):'')+' / 16';$('readerPrev').disabled=current===0;$('readerNext').disabled=current>=15;$('readerChapter').value=current;$('readerEdition').textContent=en?'English reading edition':'Édition originale · français';$('readerHint').textContent=en?'Drag a corner or tap an edge to turn the page.':'Glissez un coin ou touchez le bord pour tourner la page.'}
function chapters(){const arr=lang()==='en'?enTitles:titles;$('readerChapter').innerHTML=arr.map((t,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} · ${t}</option>`).join('')}
function open(page=0){requestedPage=page;reader.showModal();document.body.style.overflow='hidden';chapters();requestAnimationFrame(()=>{if(!flip){if(!window.St?.PageFlip){$('flipBook').innerHTML='<p>Le lecteur ne peut pas être chargé. Téléchargez le PDF original.</p>';return}const maxH=Math.min(693,Math.max(325,innerHeight-285));flip=new St.PageFlip($('flipBook'),{startPage:page,width:440,height:622,size:'stretch',minWidth:210,maxWidth:maxH*595.5/842.25,minHeight:297,maxHeight:maxH,showCover:true,autoSize:true,maxShadowOpacity:.45,flippingTime:matchMedia('(prefers-reduced-motion: reduce)').matches?1:850,usePortrait:true,mobileScrollSupport:false,drawShadow:true,showPageCorners:true});flip.on('init',()=>{flip.turnToPage(requestedPage);current=requestedPage;controls()});flip.on('flip',e=>{current=e.data;controls()});flip.on('changeOrientation',controls);flip.loadFromHTML(pageNodes())}flip.turnToPage(page);current=page;controls()})}
function close(){reader.close();document.body.style.overflow=''}
$('readMagazine').onclick=()=>open();$('coverRead').onclick=()=>open();document.querySelectorAll('[data-mag-page]').forEach(b=>b.onclick=()=>open(+b.dataset.magPage));$('readerClose').onclick=close;reader.addEventListener('close',()=>document.body.style.overflow='');$('readerPrev').onclick=()=>flip?.flipPrev('bottom');$('readerNext').onclick=()=>flip?.flipNext('bottom');$('readerChapter').onchange=e=>{current=+e.target.value;requestedPage=current;flip?.turnToPage(current);controls()};
$('readerFocus').onclick=()=>{const f=$('focusContent');f.dataset.noTranslate='';f.innerHTML=pageHTML(current);$('pageFocus').showModal()};$('focusClose').onclick=()=>$('pageFocus').close();document.addEventListener('keydown',e=>{if(!reader.open||$('pageFocus').open||e.target.tagName==='SELECT')return;if(e.key==='ArrowRight'){e.preventDefault();flip?.flipNext('bottom')}if(e.key==='ArrowLeft'){e.preventDefault();flip?.flipPrev('bottom')}});
$('magRunway').onclick=()=>window.siteShow('landing');$('magJourney').onclick=()=>window.siteShow('landing');$('magStudio').onclick=()=>window.siteShow('room');
window.addEventListener('languagechange',()=>{chapters();if(flip){flip.updateFromHtml(pageNodes());flip.turnToPage(current)}controls();if($('pageFocus').open)$('focusContent').innerHTML=pageHTML(current)});chapters();controls();
$('enlargeQR').onclick=()=>$('qrDialog').showModal();$('qrCard').onclick=()=>$('qrDialog').showModal();$('closeQR').onclick=()=>$('qrDialog').close();
})();
